:root {
  --bg: #1a1c2c;
  --card: #f4f4f4;
  --ink: #1a1c2c;
  --accent: #ff6b6b;
  --accent-dark: #c44;
  --muted: #5a5c6c;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--ink);
  padding: 16px;
}
.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--accent);
  padding: 24px;
}
h1 {
  margin: 0 0 20px;
  font-size: 1.6rem;
  letter-spacing: 1px;
  text-transform: uppercase;
}
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type='text'] {
  flex: 1;
  min-width: 0;
  padding: 10px;
  font: inherit;
  border: 3px solid var(--ink);
  background: #fff;
  color: var(--ink);
}
input[type='text']:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
button {
  font: inherit;
  font-weight: 700;
  padding: 10px 16px;
  border: 3px solid var(--ink);
  background: var(--accent);
  color: var(--ink);
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--ink);
  transition: transform 0.05s, box-shadow 0.05s;
}
button:hover { background: var(--accent-dark); }
button:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; }
button:active { transform: translate(3px, 3px); box-shadow: none; }
.counts {
  margin: 0 0 16px;
  font-weight: 700;
  color: var(--muted);
}
.counts span { color: var(--ink); }
ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 3px solid var(--ink);
  background: #fff;
}
li input[type='checkbox'] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
li input[type='checkbox']:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.task-text {
  flex: 1;
  word-break: break-word;
}
.task-text.done {
  text-decoration: line-through;
  color: var(--muted);
}
li button {
  padding: 6px 10px;
  font-size: 0.9rem;
  background: var(--card);
}
li button:hover { background: var(--accent); }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

let nextId = 1;
const tasks = [];

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
const list = document.getElementById('todo-list');

function updateCounts() {
  totalEl.textContent = String(tasks.length);
  remainingEl.textContent = String(tasks.filter(t => !t.done).length);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const id = nextId++;
  const task = { id, text, done: false };
  tasks.push(task);
  input.value = '';
  renderTask(task);
  updateCounts();
  input.focus();
}

function renderTask(task) {
  const li = document.createElement('li');

  const check = document.createElement('input');
  check.type = 'checkbox';
  check.id = `todo-check-${task.id}`;
  check.setAttribute('aria-label', `Mark "${task.text}" complete`);
  check.addEventListener('change', () => {
    task.done = check.checked;
    span.classList.toggle('done', task.done);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.className = 'task-text';
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.id = `todo-delete-${task.id}`;
  del.textContent = 'Delete';
  del.setAttribute('aria-label', `Delete "${task.text}"`);
  del.addEventListener('click', () => {
    const i = tasks.indexOf(task);
    if (i !== -1) tasks.splice(i, 1);
    li.remove();
    updateCounts();
  });

  li.append(check, span, del);
  list.appendChild(li);
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    addTask();
  }
});

updateCounts();
